<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserMfaRecoveryCode\Domain\Event;

use Override;
use Civi\Lughauth\Features\Access\UserMfaRecoveryCode\Domain\UserMfaRecoveryCode;
use Civi\Lughauth\Shared\Event\PublicEvent;

class UserMfaRecoveryCodeUpdateEvent extends UserMfaRecoveryCodeEvent implements PublicEvent
{
    public function __construct(
        UserMfaRecoveryCode $payload,
        public readonly UserMfaRecoveryCode $original
    ) {
        parent::__construct($payload);
    }
    #[Override]
    public function eventType(): string
    {
        return 'user-mfa-recovery-code.update';
    }
    #[Override]
    public function schemaVersion(): string
    {
        return 'v1';
    }
    #[Override]
    public function payload(): array
    {
        return $this->payload->asPublicJson();
    }
    #[Override]
    public function original(): array
    {
        return $this->original->asPublicJson();
    }
}
